_T_CASE = 27.0
_T_SERIE = 7.5
_T_TEL = 6.0


def _poser_decor(c, x0, y0):
    """Grave la planche UNE FOIS par document, puis la tamponne.
    ⚠️ La marque est posée SUR LE CANEVAS, jamais dans un dictionnaire
    indexé par id() : Python réutilise les id() libérés."""
    nom = "B8_18_DECOR"
    if not getattr(c, "_b818_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=FEUILLE_W, uppery=FEUILLE_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0
            n = len(contour)
            while i < n:
                cmd = contour[i]
                j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                else:
                    p.curveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H,
                              v[2] / 1000.0 * FEUILLE_W, FEUILLE_H - v[3] / 1000.0 * FEUILLE_H,
                              v[4] / 1000.0 * FEUILLE_W, FEUILLE_H - v[5] / 1000.0 * FEUILLE_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._b818_forme_faite = True
    c.saveState()
    c.translate(x0, y0)
    c.doForm(nom)
    c.restoreState()


def _gen_grille(rng):
    """Une grille : par plage, DEUX numeros differents, le petit d'abord.
    Les huit places, de gauche a droite : B B | I I  ||  G G | O O."""
    vals = []
    for a, b in RANGES:
        x, y = sorted(rng.sample(range(a, b + 1), 2))
        vals.append(x)
        vals.append(y)
    return vals


# ⚠️⚠️ DEUX GRILLES IDENTIQUES DANS LA MEME RAME : ce jeu ne peut fabriquer
#    que 105^4 = 121 550 625 grilles differentes. Une rame de 500 feuilles en
#    contient 9 000 : le calcul donne UNE CHANCE SUR TROIS qu'une paire s'y
#    trouve. On garde donc en memoire, pendant tout le document, les grilles
#    deja sorties.
def _tirer(rng, deja):
    for _ in range(200):
        g = _gen_grille(rng)
        cle = tuple(g)
        if cle not in deja:
            deja.add(cle)
            return g
    return g


def _dessiner_feuille(c, x0, y0, grilles, series, couleur_hex, titre_jeu="",
                      telephone="", style="eco"):
    police_ch, gris_ch = _style_chiffres(style)
    col = colors.HexColor(couleur_hex)
    c.setFillColor(col)
    _poser_decor(c, x0, y0)

    def MX(v):
        return x0 + v / 1000.0 * FEUILLE_W

    def MY(v):
        return y0 + FEUILLE_H - v / 1000.0 * FEUILLE_H

    for gi, (bord, bandeau, cases, rangee) in enumerate(GRILLES):
        vals = grilles[gi]
        cy = MY((rangee[0] + rangee[1]) / 2.0) - _T_CASE * 0.34
        for k in range(8):
            cx = MX((cases[k] + cases[k + 1]) / 2.0)
            if _sec:
                _sec.chiffre_micro(c, vals[k], cx, cy, _T_CASE, gris_ch, police_ch,
                                   epaisseur=_GRAS_TRAIT)
            else:
                c.setFillColor(gris_ch)
                c.setFont(police_ch, _T_CASE)
                c.drawCentredString(cx, cy, str(vals[k]))
        # ⭐ le numero de serie se pose JUSTE APRES SON « N° », dans le bandeau
        c.setFillColor(GRIS)
        c.setFont(POLICE, _T_SERIE)
        c.drawString(MX(cases[0]) + 5.2 * mm, MY(bandeau[1]) + 2.5 * mm,
                     "%06d" % series[gi])
        if telephone:
            c.setFont(POLICE, _T_TEL)
            c.drawRightString(MX(cases[8]) - 0.8 * mm, MY(bandeau[1]) + 2.5 * mm,
                              telephone[:14])
        if _sec:
            try:
                _sec.cadre_micro(c, MX(bord[0]), MY(rangee[1]),
                                 MX(bord[1]) - MX(bord[0]),
                                 MY(bandeau[0]) - MY(rangee[1]),
                                 series[gi], retrait=0.7 * mm)
            except Exception:
                pass


def generer_pdf(nb_cartes=18, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", motif="",
                page_start=1, **_):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=landscape(A4), pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE

    rng = random.Random(880000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    _deja = set()

    for _p in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 8)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 4.6 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 4.6 * mm, "%03d" % no_page)

        grilles = [_tirer(rng, _deja) for _k in range(CARTES_PAGE)]
        series = [serie + k for k in range(CARTES_PAGE)]
        coul = (couleur_perso if (couleur and couleur_perso)
                else RAINBOW[(serie - 1) % len(RAINBOW)] if couleur else TRAIT_NB)
        _dessiner_feuille(c, MARGE_X, MARGE_Y, grilles, series, coul,
                          titre_jeu, telephone, style=style)
        serie += CARTES_PAGE
        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
    return buf


